def forward(groups):
    parts = groups[0].split('_')
    stored = [int(parts[0]), int(parts[1]), parts[2], int(parts[3]), int(parts[4])]
    return {'stored': stored, 'layout': ['_', '_', '_', '_']}

def inverse(record):
    return 'attempt_' + '_'.join([
        str(record['stored'][0]),
        str(record['stored'][1]),
        record['stored'][2],
        str(record['stored'][3]),
        str(record['stored'][4])
    ])
